package io.knowledgebrain.planning;
import java.util.*;import java.util.concurrent.*;import java.time.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.flywaydb.core.Flyway;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_PLANNING_DATABASE_URL",matches=".+")
class RecurrenceStoreIntegrationTest {
 PGSimpleDataSource ds;JdbcTemplate sql;ScheduleStore store;TaskStore tasks;RecurrenceStore series;String schema;final UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space,actor;final String trace="b".repeat(32);
 @BeforeEach void init(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_PLANNING_DATABASE_URL"));ds.setUser("brain_planning");ds.setPassword(System.getenv("BRAIN_TEST_PLANNING_DATABASE_PASSWORD"));schema="schedule_test_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(ds).execute("CREATE SCHEMA "+schema);ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();sql=new JdbcTemplate(ds);store=new ScheduleStore(ds,Clock.systemUTC());tasks=new TaskStore(ds,Clock.systemUTC());series=new RecurrenceStore(ds,Clock.systemUTC());space=ids.next();actor=ids.next();}
 @AfterEach void cleanup(){sql.execute("DROP SCHEMA "+schema+" CASCADE");}
 String key(){return UUID.randomUUID().toString().replace("-","");}

 RecurrenceRules.Input input(int count,UUID task){return new RecurrenceRules.Input("Recurring"," original\n","2028-10-30T09:00:00","2028-10-30T10:00:00","America/New_York",task,"DAILY",1,count,"REJECT","REJECT");}
 RecurrenceStore.Series create(int count,UUID task){var i=input(count,task);return series.create(space,actor,key(),i,series.preview(space,i).previewHash(),trace).recurrence();}
 void status(int expected,Runnable fn){assertEquals(expected,assertThrows(ResponseStatusException.class,fn::run).getStatusCode().value());}
 int count(String table){return sql.queryForObject("SELECT count(*) FROM "+table,Integer.class);}
 @Test void hundredOccurrenceSeriesIsAtomicAndKeepsOriginalCreationAcrossClaimsAndRetirement(){var task=tasks.create(space,actor,key(),new TaskStore.Input("Task","","COMPLETED","1582-10-10",null),trace).task();String key=key();var i=input(100,task.taskId());var p=series.preview(space,i);var original=series.create(space,actor,key,i,p.previewHash(),trace);assertFalse(original.replay());var v=original.recurrence();assertEquals(100,v.occurrences().size());assertEquals(100,count("schedule"));assertEquals(102,count("outbox_event"));assertEquals(task,tasks.get(space,task.taskId()));var cancellation=series.cancellation(space,v.recurrenceId(),50);assertEquals(51,cancellation.items().size());var retired=series.cancel(space,v.recurrenceId(),ids.next(),1,50,cancellation.cancellationHash(),trace);assertEquals(2,retired.version());assertEquals("RETIRED",retired.state());assertEquals(49,sql.queryForObject("SELECT count(*) FROM schedule WHERE state='ACTIVE'",Integer.class));assertEquals(51,sql.queryForObject("SELECT count(*) FROM schedule WHERE state='RETIRED'",Integer.class));assertEquals(retired,series.cancel(space,v.recurrenceId(),actor,1,50,cancellation.cancellationHash(),trace));assertEquals(154,count("outbox_event"));tasks.change(space,task.taskId(),actor,1,null,true,trace);assertEquals(v,series.create(space,ids.next(),key,i,p.previewHash(),trace).recurrence());assertEquals(v,series.history(space,v.recurrenceId(),2,5).getFirst().snapshot());assertEquals(retired,series.get(space,v.recurrenceId()));assertEquals(v.recurrenceId(),series.list(space,"RETIRED",null,20).items().getFirst().recurrenceId());}
 @Test void stalePreviewOrUnavailableTaskNeverLeavesPartialChildren(){var i=input(3,null);status(412,()->series.create(space,actor,key(),i,"a".repeat(64),trace));assertEquals(0,count("recurrence"));assertEquals(0,count("schedule"));var foreign=tasks.create(ids.next(),actor,key(),new TaskStore.Input("Foreign","","NOT_STARTED",null,null),trace).task();status(404,()->series.create(space,actor,key(),input(3,foreign.taskId()),RecurrenceRules.preview(space,input(3,foreign.taskId())).previewHash(),trace));assertEquals(0,count("schedule"));var v=create(2,null);status(404,()->series.get(actor,v.recurrenceId()));status(404,()->series.cancellation(actor,v.recurrenceId(),1));assertThrows(RuntimeException.class,()->sql.update("UPDATE recurrence_occurrence SET space_id=? WHERE recurrence_id=?",actor,v.recurrenceId()));}
 @Test void childEditsAndRetirementsInvalidateBulkConfirmationWhileEarlierOccurrencesStayIndependent(){var v=create(4,null);var first=v.occurrences().getFirst();var second=v.occurrences().get(1);var preview=series.cancellation(space,v.recurrenceId(),2);assertEquals(3,preview.items().size());var original=store.get(space,second.scheduleId());store.change(space,second.scheduleId(),actor,1,new ScheduleStore.Input("Individually moved","",original.startsAt(),original.endsAt(),original.timeZone(),null),false,trace);status(412,()->series.cancel(space,v.recurrenceId(),actor,1,2,preview.cancellationHash(),trace));assertEquals("ACTIVE",series.get(space,v.recurrenceId()).state());assertEquals(4,sql.queryForObject("SELECT count(*) FROM schedule WHERE state='ACTIVE'",Integer.class));store.change(space,v.occurrences().get(2).scheduleId(),actor,1,null,true,trace);var fresh=series.cancellation(space,v.recurrenceId(),2);assertEquals(List.of(2,4),fresh.items().stream().map(RecurrenceStore.Candidate::ordinal).toList());var before=store.get(space,first.scheduleId());series.cancel(space,v.recurrenceId(),actor,1,2,fresh.cancellationHash(),trace);assertEquals(before,store.get(space,first.scheduleId()));assertEquals(3,store.history(space,second.scheduleId(),Long.MAX_VALUE,5).getFirst().version());assertEquals("Individually moved",store.history(space,second.scheduleId(),Long.MAX_VALUE,5).getFirst().snapshot().title());}
 @Test void parentOutboxFailuresRollBackAlreadyWrittenChildrenOnCreateAndCancellation(){sql.execute("CREATE FUNCTION fail_recurrence_outbox() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.aggregatetype='recurrence' THEN RAISE EXCEPTION 'controlled recurrence failure'; END IF; RETURN NEW; END $$");sql.execute("CREATE TRIGGER fail_recurrence_outbox BEFORE INSERT ON outbox_event FOR EACH ROW EXECUTE FUNCTION fail_recurrence_outbox()");assertThrows(RuntimeException.class,()->create(5,null));assertEquals(0,count("recurrence"));assertEquals(0,count("schedule"));assertEquals(0,count("outbox_event"));sql.execute("ALTER TABLE outbox_event DISABLE TRIGGER fail_recurrence_outbox");var v=create(5,null);var p=series.cancellation(space,v.recurrenceId(),1);sql.execute("ALTER TABLE outbox_event ENABLE TRIGGER fail_recurrence_outbox");assertThrows(RuntimeException.class,()->series.cancel(space,v.recurrenceId(),actor,1,1,p.cancellationHash(),trace));assertEquals(6,count("outbox_event"));assertEquals(5,count("schedule_revision"));assertEquals(1,series.get(space,v.recurrenceId()).version());assertEquals(5,series.cancellation(space,v.recurrenceId(),1).items().size());}
 @Test void concurrentCreationAndCancellationRetryHasOneCanonicalOutcome()throws Exception{var i=input(3,null);String hash=RecurrenceRules.preview(space,i).previewHash(),key=key();try(var pool=Executors.newFixedThreadPool(2)){var gate=new CyclicBarrier(2);var a=pool.submit(()->{gate.await();return series.create(space,actor,key,i,hash,trace);});var z=pool.submit(()->{gate.await();return series.create(space,actor,key,i,hash,trace);});var first=a.get();var second=z.get();assertEquals(first.recurrence(),second.recurrence());assertNotEquals(first.replay(),second.replay());var v=first.recurrence();var p=series.cancellation(space,v.recurrenceId(),1);var cancelGate=new CyclicBarrier(2);var results=new ArrayList<Future<RecurrenceStore.Series>>();for(int n=0;n<2;n++)results.add(pool.submit(()->{cancelGate.await();return series.cancel(space,v.recurrenceId(),actor,1,1,p.cancellationHash(),trace);}));assertEquals(results.get(0).get(),results.get(1).get());assertEquals(8,count("outbox_event"));assertEquals(2,count("recurrence_revision"));}}
 @Test void catalogueCursorBindsSpaceAndLifecycle(){for(int n=0;n<23;n++)create(2,null);var a=series.list(space,"ACTIVE",null,20);var z=series.list(space,"ACTIVE",a.nextAfter(),20);assertEquals(20,a.items().size());assertEquals(3,z.items().size());assertNull(z.nextAfter());status(400,()->series.list(actor,"ACTIVE",a.nextAfter(),20));status(400,()->series.list(space,"RETIRED",a.nextAfter(),20));assertEquals(23,count("recurrence"));}
}
